// Title: C# add a custom Table id prefix to each <table> in Aspose.Cells HTML export and verify the IDs
// Common Searches: how to inject a custom id attribute into tables generated by Aspose.Cells HTML export using C# | C# regex to add and check Table id prefixes on <table> tags in Aspose.Cells HTML output | validate that every table element in Aspose.Cells HTML has an id starting with a specific prefix | Aspose.Cells HTMLSaveOptions example for post‑processing table IDs in C# | programmatically ensure correct table id naming in HTML produced by Aspose.Cells
// Tags: Aspose.Cells add table id attribute C# | regex modify Aspose.Cells HTML output | validate table id prefix Aspose.Cells | HtmlSaveOptions post‑process table identifiers | custom table ids in exported HTML

using System;
using System.IO;
using System.Text.RegularExpressions;
using Aspose.Cells;

// The example creates a workbook, saves it to HTML with Aspose.Cells, then uses regular expressions in C# to insert an id attribute prefixed with "Table" into each <table> element. After injection, it scans the HTML to confirm every table's id begins with the required prefix and reports the validation result.
class Program
{
    static void Main()
    {
        try
        {
            // Create a workbook and add sample data
            var workbook = new Workbook();
            var sheet = workbook.Worksheets[0];
            sheet.Cells["A1"].PutValue("Header1");
            sheet.Cells["B1"].PutValue("Header2");
            sheet.Cells["A2"].PutValue("Data1");
            sheet.Cells["B2"].PutValue("Data2");

            // Export the workbook to HTML (no TableCssIdPrefix property in current API)
            var htmlOptions = new HtmlSaveOptions
            {
                ExportActiveWorksheetOnly = true
            };

            string htmlContent;
            using (var ms = new MemoryStream())
            {
                workbook.Save(ms, htmlOptions);
                ms.Position = 0;
                using (var reader = new StreamReader(ms))
                {
                    htmlContent = reader.ReadToEnd();
                }
            }

            // Add id attributes to each <table> element with the required prefix
            const string prefix = "Table";
            int tableIndex = 1;
            var tableTagRegex = new Regex(@"<table\b([^>]*)>", RegexOptions.IgnoreCase);
            var idAttrRegex = new Regex(@"id\s*=\s*[""']([^""']+)[""']", RegexOptions.IgnoreCase);

            htmlContent = tableTagRegex.Replace(htmlContent, match =>
            {
                string attributes = match.Groups[1].Value;
                // If an id already exists, leave the tag unchanged
                if (idAttrRegex.IsMatch(attributes))
                {
                    return match.Value;
                }

                // Insert a new id attribute with the required prefix
                string newAttributes = $" id=\"{prefix}{tableIndex}\"{attributes}";
                tableIndex++;
                return $"<table{newAttributes}>";
            });

            // Validate that each <table> now has an id starting with the prefix
            bool allValid = true;
            var tableRegex = new Regex(@"<table\b[^>]*>", RegexOptions.IgnoreCase);
            var idRegex = new Regex(@"id\s*=\s*[""']([^""']+)[""']", RegexOptions.IgnoreCase);

            foreach (Match tableMatch in tableRegex.Matches(htmlContent))
            {
                string tableTag = tableMatch.Value;
                var idMatch = idRegex.Match(tableTag);
                string id = idMatch.Success ? idMatch.Groups[1].Value : null;

                if (string.IsNullOrEmpty(id) || !id.StartsWith(prefix, StringComparison.Ordinal))
                {
                    allValid = false;
                    Console.WriteLine($"Invalid table id: '{id ?? "null"}'");
                }
            }

            Console.WriteLine(allValid ? "All table ids have correct prefix." : "Some table ids are invalid.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
